import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation","description":"Install Ask Access on a Pterodactyl panel via Blueprint or the standalone installer, verify it works, and uninstall cleanly.","frontmatter":{"title":"Installation","description":"Install Ask Access on a Pterodactyl panel via Blueprint or the standalone installer, verify it works, and uninstall cleanly."},"headers":[],"relativePath":"ask-access/getting-started/installation.md","filePath":"ask-access/getting-started/installation.md","lastUpdated":null}'),l={name:"ask-access/getting-started/installation.md"};function n(r,s,o,d,h,p){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Ask Access installs like any other Pterodactyl addon. Pick the path that matches your panel.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Pterodactyl Panel <strong>v1.11+</strong> at <code>/var/www/pterodactyl</code></li><li><strong>PHP 8.1+</strong>, <strong>Composer</strong>, <strong>python3</strong></li><li><strong>Node.js + Yarn</strong> (to rebuild the client frontend)</li><li>The panel&#39;s scheduler cron already configured (standard for any Pterodactyl install):</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> php /var/www/pterodactyl/artisan schedule:run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /dev/null </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;&amp;1</span></span></code></pre></div><ul><li><a href="https://blueprint.zip" target="_blank" rel="noreferrer">Blueprint</a> installed on the panel — <strong>required for the Blueprint package</strong>, and strongly recommended for standalone installs too (the account page route is wired through Blueprint&#39;s extends layer)</li></ul><hr><h2 id="blueprint-install-recommended" tabindex="-1">Blueprint install (recommended) <a class="header-anchor" href="#blueprint-install-recommended" aria-label="Permalink to &quot;Blueprint install (recommended)&quot;">​</a></h2><ol><li><p>Download <code>pterodactylaskaccess-v1.0.0.blueprint</code> from the <a href="https://github.com/AnAverageBeing/Ask-Access/releases" target="_blank" rel="noreferrer">latest release</a> and place it in your panel directory.</p></li><li><p>Install:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylaskaccess-v1.0.0.blueprint</span></span></code></pre></div><p>Blueprint merges the addon files, registers the service provider, wires the client routes, runs the migrations, and rebuilds the frontend.</p><hr><h2 id="standalone-install" tabindex="-1">Standalone install <a class="header-anchor" href="#standalone-install" aria-label="Permalink to &quot;Standalone install&quot;">​</a></h2><ol><li>Download <code>AskAccess-v1.0.0-standalone.zip</code> from the <a href="https://github.com/AnAverageBeing/Ask-Access/releases" target="_blank" rel="noreferrer">latest release</a>, unzip it, and enter the folder:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AskAccess-v1.0.0-standalone.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> askaccess</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> askaccess</span></span></code></pre></div><ol start="2"><li>Run the installer as root:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>If your panel lives somewhere other than <code>/var/www/pterodactyl</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PTERODACTYL_DIRECTORY=/path/to/panel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>The installer will:</p><ul><li>create a full panel backup under <code>/var/backups/pterodactyl-askaccess-&lt;timestamp&gt;</code></li><li>merge <code>PanelFiles/</code> into the panel</li><li>register <code>AskAccessServiceProvider</code> in <code>config/app.php</code> (idempotent)</li><li>register the <code>accessmanager.manage</code> subuser permission in <code>app/Models/Permission.php</code></li><li>wire the <strong>Server Access</strong> account route into Blueprint&#39;s extends layer (if present)</li><li>rebuild the Composer autoloader and run the database migrations</li><li>rebuild the client assets (<code>yarn build:production</code>)</li><li>fix ownership, clear caches, and restart the queue worker</li></ul><div class="tip custom-block"><p class="custom-block-title">Re-running is safe</p><p>Both installers are idempotent — running them twice won&#39;t duplicate providers, permissions, routes, or tables.</p></div><hr><h2 id="verify-the-install" tabindex="-1">Verify the install <a class="header-anchor" href="#verify-the-install" aria-label="Permalink to &quot;Verify the install&quot;">​</a></h2><ol><li>Log in to the client area and open <strong>Account → Server Access</strong> — the page should load without errors.</li><li>Check the database tables exist:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tinker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --execute=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;echo implode(&#39; &#39;, \\Illuminate\\Support\\Facades\\Schema::getColumnListing(&#39;askaccess_requests&#39;));&quot;</span></span></code></pre></div><p>You should see <code>askaccess_requests</code>, <code>askaccess_settings</code>, <code>askaccess_blocks</code>, <code>askaccess_logs</code>, <code>askaccess_grants</code>, and <code>askaccess_admin_settings</code> in your database.</p><ol start="3"><li>Confirm the scheduler is pruning:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> askaccess:prune</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [Ask Access] Expired 0 pending request(s); revoked 0 temporary grant(s).</span></span></code></pre></div><ol start="4"><li>Admin settings live at <strong>Admin → Extensions → Ask Access</strong> (Blueprint installs).</li></ol><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Server Access</code> page missing from Account menu</td><td>Frontend not rebuilt or route not wired</td><td><code>cd /var/www/pterodactyl &amp;&amp; yarn build:production</code>, then hard-refresh (Ctrl+Shift+R)</td></tr><tr><td>Page loads but shows a 404 on API calls</td><td>Routes cached before install</td><td><code>php artisan route:clear &amp;&amp; php artisan optimize:clear</code></td></tr><tr><td><code>Class &#39;Pterodactyl\\Services\\AskAccess\\...&#39; not found</code></td><td>Autoloader not rebuilt</td><td><code>composer dump-autoload --optimize</code> in the panel dir</td></tr><tr><td>Migration errors about existing tables</td><td>Partial previous install</td><td>Safe — migrations check <code>hasTable</code>/<code>hasColumn</code> before creating; re-run <code>php artisan migrate --force</code></td></tr><tr><td>Temporary access never expires</td><td>Scheduler cron missing</td><td>Add the <code>schedule:run</code> cron entry (see Prerequisites)</td></tr><tr><td>Build fails on Node 17+</td><td>OpenSSL 3 legacy provider</td><td>The installer sets this automatically; manually: <code>NODE_OPTIONS=--openssl-legacy-provider yarn build:production</code></td></tr><tr><td>Blank page after install</td><td>File ownership</td><td><code>chown -R www-data:www-data /var/www/pterodactyl</code></td></tr></tbody></table><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p><strong>Blueprint:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylaskaccess</span></span></code></pre></div><p><strong>Standalone:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div><p>Both paths remove the provider registration, the custom permission, the frontend route, and the addon&#39;s files. <strong>Database tables are left intact</strong> so no access history is lost. To fully purge:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:rollback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path=database/migrations/2026_06_03_100000_askaccess_grants_and_limits.php</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:rollback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path=database/migrations/2026_06_02_100000_extend_askaccess.php</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:rollback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path=database/migrations/2026_06_01_100000_create_askaccess_tables.php</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Rolling back drops data</p><p>The rollback commands above <strong>drop</strong> every <code>askaccess_*</code> table, including the audit log and all grant records. There is no undo.</p></div>`,42)])])}const g=a(l,[["render",n]]);export{k as __pageData,g as default};
